import numpy as np

def check_constraints(grid_size, R_coords, B_coords):
    # 1. Constraint C2 Check (Internal Independence)
    # Check R
    for r1 in R_coords:
        for r2 in R_coords:
            if r1 == r2:
                continue
            # Check if r1 and r2 share a side or vertex (King's move distance <= 1)
            if abs(r1[0] - r2[0]) <= 1 and abs(r1[1] - r2[1]) <= 1:
                print(f"C2 Violation (Red): {r1} and {r2} are adjacent.")
                return False

    # Check B
    for b1 in B_coords:
        for b2 in B_coords:
            if b1 == b2:
                continue
            # Check if b1 and b2 share a side or vertex
            if abs(b1[0] - b2[0]) <= 1 and abs(b1[1] - b2[1]) <= 1:
                print(f"C2 Violation (Blue): {b1} and {b2} are adjacent.")
                return False

    # 2. Constraint C1 Check (Local Sparsity in S)
    S_coords = R_coords + B_coords
    k = len(S_coords)

    # Map coordinates to index for quick lookup
    s_set = set(S_coords)

    for s in S_coords:
        neighbors_count = 0
        # Check all 8 neighbors + self (though self is excluded)
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                neighbor = (s[0] + dr, s[1] + dc)
                if neighbor in s_set:
                    neighbors_count += 1

        if neighbors_count > 1:
            print(f"C1 Violation (Local Sparsity): Square {s} has {neighbors_count} neighbors in S.")
            return False

    print("All constraints satisfied.")
    return True

# --- Test Case 1: Standard 2/9 tiling (Period 3) ---
# R at (1, 1) mod 3, B at (3, 3) mod 3 (using 0-indexing: (0, 0) and (2, 2))
N = 125
R_coords_29 = []
B_coords_29 = []
for i in range(N):
    for j in range(N):
        # R position: (i % 3 == 0 and j % 3 == 0)
        if i % 3 == 0 and j % 3 == 0:
            R_coords_29.append((i, j))
        # B position: (i % 3 == 2 and j % 3 == 2)
        if i % 3 == 2 and j % 3 == 2:
            B_coords_29.append((i, j))

print("--- Testing 2/9 Configuration ---")
check_constraints(N, R_coords_29, B_coords_29)

# --- Test Case 2: Attempt to push density by placing R and B adjacent (Period 2 pattern) ---
# R at (0, 0) mod 2, B at (0, 1) mod 2 (Highly dense, should fail C2 and C1)
R_coords_dense = []
B_coords_dense = []
for i in range(N):
    for j in range(N):
        if i % 2 == 0 and j % 2 == 0:
            R_coords_dense.append((i, j))
        if i % 2 == 0 and j % 2 == 1:
            B_coords_dense.append((i, j))

print("\n--- Testing Dense Configuration (Period 2) ---")
check_constraints(N, R_coords_dense, B_coords_dense)
